// Paste your Base64 strings here:
const LOGO_BASE64 = "data:image/png;base64,";
const KNOB_BASE64 = "data:image/png;base64,";
const SWITCH_BASE64 = "data:image/png;base64,";

class View extends HTMLElement {
    constructor(patchConnection) {
        super();
        this.patchConnection = patchConnection;
        this.attachShadow({ mode: 'open' });
        this.shadowRoot.innerHTML = this.getHTML();
    }

    connectedCallback() {
        this.setupKnobs();
        this.setupSwitch();
        this.setupEventListeners();
    }

    getHTML() {
        return `
            <style>
                * {
                    margin: 0;
                    padding: 0;
                }

                :host {
                    display: block;
                    width: 100%;
                    height: 100%;
                    max-height: 100%;
                    max-width: 100%;
                    overflow: hidden;
                    position: relative;

                    background: linear-gradient(
                        135deg,
                        #2d2e32 0%,
                        #27282b 25%,
                        #1c1d20 50%,
                        #202124 75%,
                        #2f3035 100%
                    );
                    box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.1), 
                        inset 0 -1px 2px rgba(0, 0, 0, 0.6),
                        0 8px 24px rgba(0, 0, 0, 0.5);
                    border: 3px solid #141416;
                }

                .container {
                    width: 100%;
                    height: 100%;
                    margin-top: 120px;
                    display: flex;
                    flex-direction: column;
                    align-items: center;
                }

                .controls {
                    display: flex;
                    flex-direction: column;
                    align-items: center; 
                }

                .controls > div {
                    display: flex;
                    gap: 32px;
                    justify-content: center;
                }

                .tresholds-clipping {
                    margin-top: 24px;
                }

                .title {
                    position: absolute;
                    top: 20px;
                    right: 50%;
                    transform: translate(50%, 0);
                    width: 200px;
                    height: auto;
                    -webkit-user-drag: none;
                }

                .knob-container, .switch-container {
                    display: flex;
                    flex-direction: column;
                    align-items: center;
                    width: 80px;
                }

                .knob, .switch {
                    width: 80px;
                    height: 80px;
                    cursor: pointer;
                    -webkit-user-drag: none;
                    user-select: none;
                    transform-origin: center center; 
                }

                .switch {
                    width: 60px;
                    height: 80px;
                    cursor: pointer;
                    -webkit-user-drag: none;
                    user-select: none;
                    object-fit: contain;
                }

                .switch.active {
                    transform: rotate(180deg);
                }

                .knob-label, .switch-label {
                    margin-top: 2px;
                    color: #c2c2c2;
                    font-family: sans-serif;
                    font-size: 12px;
                    text-transform: uppercase;
                    letter-spacing: 1px;
                    font-weight: bold;
                    text-align: center;
                }

                .knob-label span {
                    font-size: 16px;
                    display: block;
                }

                .switch-container {
                    position: relative;
                }

                .label-off, .label-on {
                    color: #c2c2c2;
                    font-size: 10px;
                    position: absolute;
                    right: -12px;
                    width: 30px;
                    text-align: center;
                    font-weight: 100;
                }
                
                .label-off {
                    top: 16px;
                }

                .label-on {
                    bottom: 44px;
                }
            </style>
            <div class="container">
                <img src="${LOGO_BASE64}" class="title">

                <div class="controls">
                    <div class="gain-lowpass-volume">
                        <div class="knob-container">
                            <img src="${KNOB_BASE64}" class="knob" id="gainKnob" draggable="false">
                            <span class="knob-label">Gain</span>
                        </div>
                        <div class="knob-container">
                            <img src="${KNOB_BASE64}" class="knob" id="toneKnob" draggable="false">
                            <span class="knob-label">Tone</span>
                        </div>
                        <div class="knob-container">
                            <img src="${KNOB_BASE64}" class="knob" id="levelKnob" draggable="false">
                            <span class="knob-label">Level</span>
                        </div>
                    </div>

                    <div class="tresholds-clipping">
                        <div class="knob-container">
                            <img src="${KNOB_BASE64}" class="knob" id="driveKnob_p" draggable="false">
                            <span class="knob-label">Treshold<span>+</span></span>
                        </div>
                        <div class="knob-container">
                            <img src="${KNOB_BASE64}" class="knob" id="driveKnob_n" draggable="false">
                            <span class="knob-label">Treshold<span>-</span></span>
                        </div>
                        <div class="switch-container">
                            <img src="${SWITCH_BASE64}" class="switch" id="clippingSwitch" draggable="false">
                            <span class="switch-label">Smooth<br>clipping</span>
                            <span class="label-off">OFF</span>
                            <span class="label-on">ON</span>
                        </div>
                    </div>
                </div>
            </div>
        `;
    }

    setKnobAngle(knobEl, normalizedValue) {
        const minAngle = -135;
        const maxAngle = 135;
        const currentAngle = minAngle + (normalizedValue * (maxAngle - minAngle));
        knobEl.style.transform = `rotate(${currentAngle}deg)`;
    }

    setupKnobs() {
        const knobMappings = [
            { id: 'gainKnob', endpoint: 'gainParam', min: 1, max: 100, isInt: true, defaultVal: 50 },
            { id: 'toneKnob', endpoint: 'toneParam', min: 0.0, max: 1.0, isInt: false, defaultVal: 0.5 },
            { id: 'levelKnob', endpoint: 'volumeParam', min: 0, max: 100, isInt: true, defaultVal: 50 },
            { id: 'driveKnob_p', endpoint: 'drive_pParam', min: 0.1, max: 1.0, isInt: false, defaultVal: 0.5 },
            { id: 'driveKnob_n', endpoint: 'drive_nParam', min: 0.1, max: 1.0, isInt: false, defaultVal: 0.5 }
        ];

        knobMappings.forEach(config => {
            const knobEl = this.shadowRoot.getElementById(config.id);
            if (!knobEl) return;

            let isDragging = false;
            let startX = 0;
            let normalizedValue = 0.5;

            this.setKnobAngle(knobEl, normalizedValue);

            knobEl.addEventListener('mousedown', (e) => {
                isDragging = true;
                startX = e.clientX;
                e.preventDefault();
            });

            const onMouseMove = (e) => {
                if (!isDragging) return;
                const deltaX = e.clientX - startX;
                startX = e.clientX;
                const sensitivity = 150;

                normalizedValue = Math.max(0, Math.min(1, normalizedValue + (deltaX / sensitivity)));
                this.setKnobAngle(knobEl, normalizedValue);

                let rawValue = config.min + (normalizedValue * (config.max - config.min));
                if (config.isInt) rawValue = Math.round(rawValue);

                if (this.patchConnection) {
                    this.patchConnection.sendEventOrValue(config.endpoint, rawValue);
                }
            };

            const onMouseUp = () => {
                isDragging = false;
            };

            window.addEventListener('mousemove', onMouseMove);
            window.addEventListener('mouseup', onMouseUp);

            knobEl._updateNormalized = (val) => {
                normalizedValue = Math.max(0, Math.min(1, (val - config.min) / (config.max - config.min)));
                this.setKnobAngle(knobEl, normalizedValue);
            };
        });
    }

    setupSwitch() {
        const switchEl = this.shadowRoot.getElementById('clippingSwitch');
        if (!switchEl) return;

        let isOn = false;

        switchEl.addEventListener('click', () => {
            isOn = !isOn;
            if (isOn) {
                switchEl.classList.add('active');
            } else {
                switchEl.classList.remove('active');
            }

            if (this.patchConnection) {
                this.patchConnection.sendEventOrValue('softClip', isOn);
            }
        });

        switchEl._updateState = (val) => {
            isOn = Boolean(val);
            if (isOn) switchEl.classList.add('active');
            else switchEl.classList.remove('active');
        };
    }

    setupEventListeners() {
        if (!this.patchConnection) return;

        this.patchConnection.addEventListener((message) => {
            if (message.type === 'event') {
                const endpointId = message.endpointId;
                const value = message.value;

                if (endpointId === 'gainParam' || endpointId === 'toneParam' || 
                    endpointId === 'volumeParam' || endpointId === 'drive_pParam' || 
                    endpointId === 'drive_nParam') {
                    const knobMap = {
                        'gainParam': 'gainKnob',
                        'toneParam': 'toneKnob',
                        'volumeParam': 'levelKnob',
                        'drive_pParam': 'driveKnob_p',
                        'drive_nParam': 'driveKnob_n'
                    };
                    const knobEl = this.shadowRoot.getElementById(knobMap[endpointId]);
                    if (knobEl && knobEl._updateNormalized) {
                        knobEl._updateNormalized(value);
                    }
                } else if (endpointId === 'softClip') {
                    const switchEl = this.shadowRoot.getElementById('clippingSwitch');
                    if (switchEl && switchEl._updateState) {
                        switchEl._updateState(value);
                    }
                }
            }
        });
    }
}

window.customElements.define("fak-view", View);

export default function createPatchView(patchConnection) {
    return new View(patchConnection);
}